import itertools

def count_all_kawaii(n):
    total_kawaii = 0
    for m in range(1, n + 1):
        count_m = 0
        for seq in itertools.product(range(1, m + 1), repeat=n):
            if len(set(seq)) == m:
                is_kawaii = True
                for k in range(2, m + 1):
                    f_km1 = seq.index(k-1)
                    # Find last occurrence of k
                    l_k = -1
                    for i in range(n - 1, -1, -1):
                        if seq[i] == k:
                            l_k = i
                            break
                    if f_km1 >= l_k:
                        is_kawaii = False
                        break
                if is_kawaii:
                    count_m += 1
        print(f"m={m}: {count_m}")
        total_kawaii += count_m
    return total_kawaii

for n_val in range(1, 6):
    print(f"n={n_val}: {count_all_kawaii(n_val)}")

